  `adelanto_q2` decimal(12,2) NOT NULL DEFAULT 0.00,
  `adelanto_q3` decimal(12,2) NOT NULL DEFAULT 0.00,
  `total_adelantos` decimal(12,2) NOT NULL DEFAULT 0.00,
  `saldo_a_cobrar` decimal(12,2) NOT NULL,
